export const MATERIAL_CLOSURE_RELEASE = Object.freeze({"version":"identity-role-closure-v1","checksum":"51bdb53e46134eb9ea7fec6156be8b3b5d34fe35b9132edc66c8097241c2f5fd","manifestSha256":"dbf7b202c8b31ca9e2587a5683b3316db28cba29b6296eae86f15bc0b1717e30","sql":"-- Core schema version identity-role-closure-v1 (closed build artifact).\n\nSET ROLE backbone_gov;\n\n-- gov/change_role.sql\n\n-- An owner or admin changes a person's role. Only an owner makes or unmakes an owner.\nCREATE OR REPLACE FUNCTION gov.change_role(p_person uuid, p_role text) RETURNS text\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog\nAS $$\n#variable_conflict use_column\nDECLARE\n  me uuid := gov._admin();\n  was text := sec.role_of(p_person);\nBEGIN\n  IF was IS NULL THEN\n    RAISE EXCEPTION 'not_found: no such person in this workspace';\n  END IF;\n  IF p_role IS NULL OR p_role NOT IN ('owner', 'admin', 'member', 'guest') THEN\n    RAISE EXCEPTION 'invalid: a role is owner, admin, member or guest';\n  END IF;\n  IF (was = 'owner' OR p_role = 'owner') AND sec.role_of(me) <> 'owner' THEN\n    RAISE EXCEPTION 'role: only an owner makes or unmakes an owner';\n  END IF;\n  UPDATE app.principals SET role = p_role WHERE workspace_id = sec.current_workspace() AND id = p_person;\n  PERFORM gov._append('person.role_changed', p_person::text, jsonb_build_object('from', was, 'to', p_role));\n  RETURN p_role;\nEND\n$$;\nREVOKE EXECUTE ON FUNCTION gov.change_role(uuid,text) FROM backbone_app;\n\n-- gov/add_person.sql\n\n-- Add a person to the workspace, as an owner or admin. Only an owner adds an owner.\nCREATE OR REPLACE FUNCTION gov.add_person(p_name text, p_email text, p_role text) RETURNS uuid\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog\nAS $$\n#variable_conflict use_column\nDECLARE\n  me uuid := gov._admin();\n  new_id uuid := gen_random_uuid();\nBEGIN\n  IF p_role IS NULL OR p_role NOT IN ('owner', 'admin', 'member', 'guest') THEN\n    RAISE EXCEPTION 'invalid: a role is owner, admin, member or guest';\n  END IF;\n  IF p_role = 'owner' AND sec.role_of(me) <> 'owner' THEN\n    RAISE EXCEPTION 'role: only an owner adds an owner';\n  END IF;\n  INSERT INTO app.principals (workspace_id, id, kind, role, name, email)\n  VALUES (sec.current_workspace(), new_id, 'person', p_role, p_name, p_email);\n  PERFORM gov._append('person.added', new_id::text, jsonb_build_object('role', p_role));\n  RETURN new_id;\nEND\n$$;\nREVOKE EXECUTE ON FUNCTION gov.add_person(text,text,text) FROM backbone_app;\n\n-- gov/accept_invitation.sql\n\n-- Accept an invitation for an account, from an empty session: the account becomes a person of the\n-- workspace, and the session is left as empty as it came.\nCREATE OR REPLACE FUNCTION gov.accept_invitation(p_token_hash text, p_user text)\nRETURNS TABLE (workspace_id uuid, principal_id uuid)\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog\nAS $$\n#variable_conflict use_column\nDECLARE\n  inv record;\n  new_id uuid := gen_random_uuid();\nBEGIN\n  IF NOT sec.session_is_empty() THEN\n    RAISE EXCEPTION 'empty_session_only: an invitation is accepted from a session that names nobody';\n  END IF;\n  SELECT * INTO inv FROM ops.invitations i\n    WHERE i.token_hash = p_token_hash AND i.accepted_at IS NULL AND i.expires_at > clock_timestamp() FOR UPDATE;\n  IF NOT FOUND THEN\n    RETURN;\n  END IF;\n  PERFORM set_config('backbone.workspace', inv.workspace_id::text, true);\n  INSERT INTO app.principals (workspace_id, id, kind, role, name, user_id)\n  VALUES (inv.workspace_id, new_id, 'person', inv.role, p_user, p_user);\n  UPDATE ops.invitations SET accepted_by = p_user, accepted_at = clock_timestamp() WHERE token_hash = p_token_hash;\n  PERFORM gov._append('person.added', new_id::text, jsonb_build_object('role', inv.role, 'invited_by', inv.invited_by), id);\n  PERFORM set_config('backbone.workspace', '', true);\n  RETURN QUERY SELECT inv.workspace_id, new_id;\nEND\n$$;\nREVOKE EXECUTE ON FUNCTION gov.accept_invitation(text,text) FROM backbone_app;\n\n-- gov/identity_add_person.sql\n\n-- Compatibility for Core clients that provision people directly. The shipped Host\n-- uses invitations; every supported person-creation path takes the identity lock.\nCREATE FUNCTION gov.identity_add_person(p_name text,p_email text,p_role text) RETURNS uuid\nLANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog\nAS $$\nBEGIN\n  PERFORM pg_advisory_xact_lock(hashtextextended('identity:'||sec.current_workspace()::text,17));\n  PERFORM gov._lock_workspace();\n  RETURN gov.add_person(p_name,p_email,p_role);\nEND\n$$;\nREVOKE ALL ON FUNCTION gov.identity_add_person(text,text,text) FROM PUBLIC,backbone_operator;\nGRANT EXECUTE ON FUNCTION gov.identity_add_person(text,text,text) TO backbone_app;\n\nRESET ROLE;\n"} as const);
